parts.text:
{
  "id": "R1",
  "summary_ko": "현수막을 들고 있어야 하는 사람 뒤로 현수막이 사라짐.",
  "claims": [
    {
      "id": "R1.S1",
      "evidence": "banners disappear behind the person that supposed to be holding it",
      "symptom_ko": "현수막을 들고 있어야 하는 사람 뒤로 현수막이 사라진다.",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "banners",
      "explicit_detail_evidence": [
        "disappear behind the person that supposed to be holding it"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "id": "R2",
  "summary_ko": "사람들이 착용한 선글라스가 얼굴에서 사라졌다 나타남",
  "claims": [
    {
      "id": "R2.S1",
      "evidence": "sunglasses on people disappear and appear on the face",
      "symptom_ko": "얼굴 위의 선글라스가 사라졌다가 다시 나타남",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "sunglasses on people",
      "explicit_detail_evidence": [
        "disappear and appear on the face"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "id": "R3",
  "summary_ko": "사람들이 들고 있던 깃발이 그들이 카메라 쪽으로 달릴 때 뒤에 떠서 따라온다.",
  "claims": [
    {
      "id": "R3.S1",
      "evidence": "The flags that the people were holding are floating behind and follow them as they run towards the camera.",
      "symptom_ko": "사람들이 들고 있던 깃발이 손에서 분리되어 뒤쪽에 뜬 채로 따라온다.",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "The flags that the people were holding",
      "explicit_detail_evidence": [
        "floating behind and follow them"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "target_relation": "same",
      "reference_claim_ids": ["R1.S1"],
      "reference_evidence": "banners disappear behind the person that supposed to be holding it",
      "candidate_evidence": "The banner initially held horizontally by the line of people breaks apart and morphs into loose fluttering cloth fragments as they begin to run.",
      "basis": "explicit_separation",
      "reason_ko": "R1은 현수막을 들고 있어야 하는 사람 뒤로 현수막이 사라지는 이상 현상을 기술하고 있는 반면, C2는 들고 있던 현수막이 부서져 펄럭이는 천 조각들로 변형되는 결함을 기술하고 있습니다. 동일한 대상을 다루고 있으나 사라지는 현상과 부서져 조각으로 변형되는 구체적인 증상이 명확히 구별되는 서로 다른 이상 증상입니다."
    }
  ]
}

{
  "pairs": [
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "target_relation": "different",
      "reference_claim_ids": [
        "R2.S1"
      ],
      "reference_evidence": "sunglasses on people disappear and appear on the face",
      "candidate_evidence": "The banner initially held horizontally by the line of people breaks apart and morphs into loose fluttering cloth fragments",
      "basis": "explicit_separation",
      "reason_ko": "참조 설명은 사람들의 얼굴에 있는 선글라스가 사라졌다 나타나는 이상 현상('sunglasses on people disappear and appear on the face')을 기술하고 있는 반면, 후보 설명은 사람들이 들고 있는 현수막이 부서지며 흩날리는 천 조각으로 변형되는 이상 현상('The banner initially held horizontally by the line of people breaks apart and morphs into loose fluttering cloth fragments')을 기술하고 있어 대상 객체 및 현상이 완전히 구분되는 별개의 결함입니다."
    }
  ]
}

{
  "pairs": [
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "target_relation": "different",
      "reference_claim_ids": ["R3.S1"],
      "reference_evidence": "The flags that the people were holding are floating behind and follow them as they run towards the camera.",
      "candidate_evidence": "The banner initially held horizontally by the line of people breaks apart and morphs into loose fluttering cloth fragments as they begin to run.",
      "basis": "explicit_separation",
      "reason_ko": "R3는 사람들이 들고 있던 깃발들(flags)이 뒤에 떠서 따라오는 공간적 추종 결함을 기술하는 반면, C2는 가로로 들려 있던 단일 현수막(The banner initially held horizontally)이 조각나며 천 파편으로 변형되는 형태학적 분해 결함을 명시적으로 기술하고 있어 서로 다른 대상과 결함 현상을 다루고 있습니다."
    }
  ]
}

